const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const store={get(k,d){try{return JSON.parse(localStorage.getItem('udyam_'+k))??d}catch{return d}},set(k,v){localStorage.setItem('udyam_'+k,JSON.stringify(v))}};
const demoPrices=[{product:'Onions',price:28,unit:'per kg',location:'Example: local market',source:'Illustrative demo',date:'2026-10-10',demo:true},{product:'Jowar flour',price:62,unit:'per kg',location:'Example: village shop',source:'Illustrative demo',date:'2026-10-09',demo:true},{product:'Handmade basket',price:180,unit:'per piece',location:'Example: weekly bazaar',source:'Illustrative demo',date:'2026-10-08',demo:true}];let prices=store.get('prices',demoPrices);let currentPage='dashboard';
const money=n=>'₹'+(Number(n)||0).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2});
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function showPage(name){currentPage=name;$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+name));$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#sidebar')?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(name==='market')renderPrices();if(name==='dashboard')renderRecent()}
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));
const fields=['productName','category','unitCost','margin','expectedDemand','stock','buffer','marketPrice','sourceName'];function getInputs(){return Object.fromEntries(fields.map(k=>[k,$('#'+k).value]))}
function calculate(){let x=getInputs(),cost=Math.max(0,+x.unitCost||0),margin=Math.max(0,+x.margin||0),demand=Math.max(0,+x.expectedDemand||0),stock=Math.max(0,+x.stock||0),buffer=Math.max(0,+x.buffer||0),market=Math.max(0,+x.marketPrice||0);let price=cost*(1+margin/100),make=Math.max(0,Math.ceil(demand*(1+buffer/100)-stock)),profit=(price-cost)*Math.min(demand,make+stock);$('#resultProduct').textContent=x.productName||'Your product';$('#suggestedPrice').textContent=money(price);$('#breakEven').textContent=money(cost);$('#makeQty').textContent=make.toLocaleString('en-IN')+' units';$('#grossProfit').textContent=money(profit);let diff=market?((price-market)/market)*100:0;$('#priceSignal').textContent=!market?'Add market price':Math.abs(diff)<5?'Close to local price':diff>0?'Above local price':'Below local price';$('#priceAdvice').textContent=!market?'Enter a verified local price to compare your target price with the market.':diff>10?'Your target is notably above the observed price. Check quality, packaging and competitor offers before setting your final price.':diff< -10?'Your target is below the observed price. Check that costs are complete and test whether customers will pay more.':'Your target price is reasonably close to the observed price; validate with a few customers.';$('#productionAdvice').innerHTML=`<ul><li>Estimated demand: <b>${demand.toLocaleString('en-IN')} units</b>.</li><li>Current stock: <b>${stock.toLocaleString('en-IN')} units</b>.</li><li>Suggested additional production: <b>${make.toLocaleString('en-IN')} units</b>, including a ${buffer}% buffer.</li><li>Start with a small batch if demand is uncertain; record actual sales and leftovers before increasing production.</li></ul><div class="signal">This is a simple demand-based estimate, not a forecast. Adjust demand using actual orders, seasonality and shelf life.</div>`;$('#priceComparison').innerHTML=`<ul><li>Cost-based target price: <b>${money(price)}</b> per unit.</li><li>Observed local price: <b>${market?money(market):'Not entered'}</b>${x.sourceName?' (source: '+escapeHtml(x.sourceName)+')':''}.</li><li>Break-even estimate: <b>${money(cost)}</b> before overheads.</li></ul><div class="signal">Include labour, packaging, transport, fees and wastage in unit cost. A competitor's price may use a different unit or quality.</div>`;['metricPrice'].forEach(k=>$('#'+k).textContent=money(price));$('#metricQty').textContent=make.toLocaleString('en-IN')+' units';$('#metricProfit').textContent=money(profit);$('#metricChannel').textContent=market&&market<price?'Direct / premium test':'Local market';renderChannels();store.set('planner',x);return {x,cost,margin,demand,stock,buffer,market,price,make,profit}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('#plannerForm').addEventListener('input',()=>calculate());$('#plannerForm').addEventListener('submit',e=>{e.preventDefault();calculate();toast('Recommendations updated')});
function renderRecent(){let list=prices.slice(-3).reverse();$('#recentPrices').innerHTML=list.map(p=>`<div class="price-row"><div><b>${escapeHtml(p.product)}</b><small>${escapeHtml(p.location)} · ${escapeHtml(p.date)}${p.demo?' · demo':''}</small></div><strong>${money(p.price)}</strong></div>`).join('')||'<p class="small">No price observations saved yet.</p>'}
function renderPrices(){let userPrices=prices.filter(p=>!p.demo);$('#priceList').innerHTML=userPrices.map((p,i)=>`<div class="price-record"><div><b>${escapeHtml(p.product)} — ${money(p.price)} <span class="muted">${escapeHtml(p.unit)}</span></b><small>📍 ${escapeHtml(p.location)}<br>Source: ${escapeHtml(p.source)} · Checked: ${escapeHtml(p.date)}</small></div><button class="delete" data-delete-price="${prices.indexOf(p)}">Delete</button></div>`).join('');$('#priceEmpty').style.display=userPrices.length?'none':'block';$$('[data-delete-price]').forEach(b=>b.addEventListener('click',()=>{prices.splice(+b.dataset.deletePrice,1);store.set('prices',prices);renderPrices();renderRecent();toast('Price observation deleted')}));}
$('#priceDate').value=new Date().toISOString().slice(0,10);$('#priceForm').addEventListener('submit',e=>{e.preventDefault();prices.push({product:$('#priceProduct').value.trim(),price:+$('#priceValue').value,unit:$('#priceUnit').value,location:$('#priceLocation').value.trim(),source:$('#priceSource').value,date:$('#priceDate').value,demo:false});store.set('prices',prices);e.target.reset();$('#priceDate').value=new Date().toISOString().slice(0,10);renderPrices();renderRecent();toast('Price observation saved on this device')});
function renderChannels(){let travel=Math.max(0,+$('#deliveryCost')?.value||20),order=Math.max(1,+$('#orderValue')?.value||250);let channels=[{name:'Direct to customers',emoji:'🤝',cost:travel+order*.02,reach:'Build trust and keep more of the sale; requires time to find and serve buyers.',ease:3},{name:'Weekly market / bazaar',emoji:'🧺',cost:Math.max(30,travel+50),reach:'Useful for testing demand face-to-face; stall, travel and unsold stock may add costs.',ease:4},{name:'Local shops / resellers',emoji:'🏪',cost:order*.15+travel*.25,reach:'Can provide repeat orders; shops may request a discount or delayed payment.',ease:4}];channels.forEach(c=>c.score=Math.max(1,Math.min(99,Math.round(100-c.cost/order*100))));channels.sort((a,b)=>b.score-a.score);$('#channelCards').innerHTML=channels.map((c,i)=>`<article class="channel ${i===0?'best':''}"><div class="emoji">${c.emoji}</div><h3>${c.name}</h3><p>${c.reach}</p><div class="cost">Estimated channel cost per order: <b>${money(c.cost)}</b></div><div class="score">${c.score}/100 <span class="muted" style="font:500 10px 'DM Sans'">cost-efficiency estimate</span></div>${i===0?'<div class="signal">Lowest estimated cost in this scenario. Validate with real quotes.</div>':''}</article>`).join('')}
$('#deliveryCost').addEventListener('input',renderChannels);$('#orderValue').addEventListener('input',renderChannels);
function download(name,content,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#downloadReport').addEventListener('click',()=>{let r=calculate();download('udyammitra-decision-summary.txt',`UDYAMMITRA DECISION SUMMARY\nGenerated: ${new Date().toLocaleString()}\nProduct: ${r.x.productName}\nCategory: ${r.x.category}\nUnit cost: ${money(r.cost)}\nTarget margin: ${r.margin}%\nSuggested price: ${money(r.price)}\nObserved market price: ${money(r.market)}\nExpected demand: ${r.demand}\nCurrent stock: ${r.stock}\nSuggested additional production: ${r.make}\nEstimated gross profit: ${money(r.profit)}\n\nNote: These are simple estimates based on user-entered data, not a live market forecast. Include all overheads and verify local prices.`);toast('Decision summary downloaded')});$('#exportPrices').addEventListener('click',()=>{let rows=[['Product','Price','Unit','Market / village','Source','Date checked'],...prices.filter(p=>!p.demo).map(p=>[p.product,p.price,p.unit,p.location,p.source,p.date])];let csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');download('udyammitra-price-book.csv',csv,'text/csv');toast('Price book exported')});
$('#language').addEventListener('change',e=>{let mr=e.target.value==='mr';document.documentElement.lang=mr?'mr':'en';$$('[data-en]').forEach(el=>el.textContent=mr?el.dataset.mr:el.dataset.en);toast(mr?'काही मजकूर मराठीत बदलला':'Language changed')});
let saved=store.get('planner',null);if(saved)fields.forEach(k=>{if(saved[k]!==undefined)$('#'+k).value=saved[k]});$('#todayLabel').textContent=new Date().toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});$('#snapshotDate').textContent='Updated '+new Date().toLocaleDateString();calculate();renderPrices();renderRecent();

