let authMode='login';
function isMarathi(){return $('#language')?.value==='mr'}
function tr(s){return isMarathi()?(translations[s]||s):s}
function translatePage(){const mr=isMarathi();document.documentElement.lang=mr?'mr':'en';document.title=mr?'उद्यममित्र — ग्रामीण व्यवसाय नियोजन':'UdyamMitra — Rural Business Intelligence';document.querySelectorAll('[data-i18n]').forEach(el=>{let k=el.dataset.i18n;if(translations[k])el.textContent=mr?translations[k]:k});document.querySelectorAll('body *').forEach(el=>{if(el.children.length===0&&el.tagName!=='SCRIPT'&&el.tagName!=='STYLE'&&!el.closest('#authOverlay')&&!el.dataset.keepText){if(!el.dataset.originalText)el.dataset.originalText=el.textContent;let original=el.dataset.originalText.trim();if(translations[original])el.textContent=mr?translations[original]:original}});document.querySelectorAll('label').forEach(el=>{if(el.htmlFor){const inp=$('#'+el.htmlFor);if(inp&&inp.placeholder){if(!inp.dataset.originalPlaceholder)inp.dataset.originalPlaceholder=inp.placeholder;const ph=inp.dataset.originalPlaceholder;inp.placeholder=mr?(translations[ph]||ph):ph}}});document.querySelectorAll('input[placeholder]').forEach(el=>{if(!el.dataset.originalPlaceholder)el.dataset.originalPlaceholder=el.placeholder;const ph=el.dataset.originalPlaceholder;el.placeholder=mr?(translations[ph]||ph):ph});$('#authHeading').textContent=tr(authMode==='login'?'Welcome back':'Create account');$('#authSubtitle').textContent=tr(authMode==='login'?'Sign in to access your business workspace.':'Create an account to keep your business workspace on this device.');$('#authSubmit').textContent=tr(authMode==='login'?'Log in':'Create my account');$('#nameField').classList.toggle('hidden',authMode!=='register');$('#authPassword').autocomplete=authMode==='login'?'current-password':'new-password';$('#signedInLabel').textContent=activeUser?tr('loggedInAs')+activeUser.name:'';$('#logoutBtn').textContent=tr('Log out');}
function setAuthMode(mode){authMode=mode;$('#loginTab').classList.toggle('active',mode==='login');$('#registerTab').classList.toggle('active',mode==='register');$('#authError').textContent='';translatePage()}
$$('[data-auth-mode]').forEach(b=>b.addEventListener('click',()=>setAuthMode(b.dataset.authMode)));
let activeUser=store.get('activeUser',null);
const accounts=store.get('accounts',[]);
function openWorkspace(user){activeUser={name:user.name,email:user.email};store.set('activeUser',activeUser);$('#authOverlay').classList.add('hidden');translatePage()}
$('#authForm').addEventListener('submit',e=>{e.preventDefault();const name=$('#authName').value.trim(),email=$('#authEmail').value.trim().toLowerCase(),password=$('#authPassword').value;$('#authError').textContent='';if(authMode==='register'){if(!name){$('#authError').textContent=tr('nameRequired');return}if(password.length<6){$('#authError').textContent=tr('weakPassword');return}if(accounts.some(a=>a.email===email)){setAuthMode('login');$('#authError').textContent=tr('accountExists');return}accounts.push({name,email,password});store.set('accounts',accounts);openWorkspace({name,email});toast(tr('accountCreated'))}else{const user=accounts.find(a=>a.email===email&&a.password===password);if(!user){$('#authError').textContent=tr('invalidLogin');return}openWorkspace(user)}});
$('#logoutBtn').addEventListener('click',()=>{store.set('activeUser',null);activeUser=null;$('#authOverlay').classList.remove('hidden');$('#authPassword').value='';setAuthMode('login');translatePage()});
$('#language').addEventListener('change',()=>{translatePage();calculate();renderRecent();renderPrices();renderChannels()});
const oldCalculate=calculate; // retain original calculations; translated content is refreshed after each render
calculate=function(){const result=oldCalculate();if($('#language').value==='mr'){translatePage();}return result};
const oldRenderRecent=renderRecent;renderRecent=function(){oldRenderRecent();if(isMarathi())translatePage()};
const oldRenderPrices=renderPrices;renderPrices=function(){oldRenderPrices();if(isMarathi())translatePage()};
const oldRenderChannels=renderChannels;renderChannels=function(){oldRenderChannels();if(isMarathi())translatePage()};
if(activeUser){$('#authOverlay').classList.add('hidden')}else{$('#authOverlay').classList.remove('hidden')}
translatePage();

